CREATE OR REPLACE FUNCTION public.check_vault_and_extensions() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_exts jsonb; v_schemas jsonb; v_tables jsonb; BEGIN SELECT jsonb_agg(name) INTO v_exts FROM pg_available_extensions WHERE name LIKE '%vault%' OR name LIKE '%sodium%' OR name LIKE '%cron%' OR name LIKE '%net%'; SELECT jsonb_agg(schema_name) INTO v_schemas FROM information_schema.schemata; SELECT jsonb_agg(table_schema || '.' || table_name) INTO v_tables FROM information_schema.tables WHERE table_schema IN ('vault', 'pgsodium', 'cron', 'net'); RETURN jsonb_build_object('extensions', v_exts, 'schemas', v_schemas, 'tables', v_tables); END; $$;